let BACKEND_CHATBOT_CHAT_SESSION_API_ENDPOINT="/api/chats";async function getChatHistory(e){var t=new URLSearchParams(window.location.search).get("sID");if(t){e=e.backendUrl||"http://localhost:8001";try{var o=await fetch(""+e+BACKEND_CHATBOT_CHAT_SESSION_API_ENDPOINT+`/sessions/${t}/history`,{method:"GET",headers:{"Content-Type":"application/json"}});if(!o.ok)throw new Error("HTTP error! status: "+o.status);var a=await o.json();if(a&&a.response)for(let t of a.response){var r=document.getElementById(t.variable);"Button"===t.question_type&&r?(r.click(),await new Promise(e=>setTimeout(e,t.data.wait_after||2))):r?r.value=t.answer:console.warn(`Element with ID '${t.variable}' not found`)}else console.error("Invalid response format")}catch(e){console.error("Error fetching data:",e)}}else console.warn("No session ID found in URL parameters")}window.getChatHistory=getChatHistory;